import ast, pathlib, sys, collections
root = pathlib.Path(sys.argv[1])
mods = {}
for p in list(root.glob("src/bmw_req/**/*.py"))+list(root.glob("api/**/*.py"))+list(root.glob("ui/*.py"))+[root/"app.py"]+list(root.glob("scripts/*.py"))+list(root.glob("tests/*.py"))+list(root.glob("pitch/*.py")):
    rel = p.relative_to(root)
    parts = list(rel.with_suffix("").parts)
    if parts[0]=="src": parts=parts[1:]
    if parts[-1]=="__init__": parts=parts[:-1]
    mods[".".join(parts)] = p
def resolve(name):
    while name:
        if name in mods: return name
        name = name.rpartition(".")[0]
edges = collections.defaultdict(set); ext=collections.Counter()
for m,p in mods.items():
    tree = ast.parse(p.read_text())
    pkg = m if p.name=="__init__.py" else m.rpartition(".")[0]
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                r=resolve(a.name); 
                if r: edges[m].add(r)
                else: ext[a.name.split(".")[0]]+=1
        elif isinstance(n, ast.ImportFrom):
            if n.level:
                base = pkg.split(".")
                base = base[:len(base)-(n.level-1)] if n.level>1 else base
                full=".".join(base+([n.module] if n.module else []))
            else: full=n.module
            for a in n.names:
                r = resolve(full+"."+a.name) or resolve(full)
                if r: edges[m].add(r)
                elif not n.level: ext[full.split(".")[0]]+=1
def reach(starts):
    seen=set(); st=list(starts)
    while st:
        x=st.pop()
        if x in seen: continue
        seen.add(x); st+= [y for y in edges[x]]
        # parent packages
        parts=x.split(".")
        for i in range(1,len(parts)):
            if ".".join(parts[:i]) in mods: st.append(".".join(parts[:i]))
    return seen
api = reach([m for m in mods if m.startswith("api")])
tests = reach([m for m in mods if m.startswith("tests")])
scripts = reach([m for m in mods if m.startswith("scripts")])
legacy = reach(["app"])
mainmods = [m for m in mods if m.endswith("__main__") or m.startswith("bmw_req")]
print("== bmw_req modules NOT reachable from api:")
for m in sorted(mods):
    if m.startswith("bmw_req") and m not in api:
        tag=[]
        if m in tests: tag.append("tests")
        if m in scripts: tag.append("scripts")
        if m in legacy: tag.append("streamlit")
        print(" ",m, tag)
print("== api imports ui?", [m for m in api if m.startswith("ui") or m=="app"])
print("== ext imports:", dict(ext))
for m in sorted(mods):
    if m.startswith(("scripts","tests")): print(m, "->", sorted(x for x in edges[m]))
EOF
